-- BIT_OR, BIT_AND and BIT_XOR as window functions, against the aggregate functions and the
-- operator `|`: strings, byte strings, floats, decimals, times with a fraction, JSON. MySQL
-- 8.0.11 refuses them (error 1235). Then each kind of frame (the whole partition, a running
-- frame, a frame whose start moves) over values from bit 31 (MDEV-35439) and NULL values
-- (MDEV-40689).
DROP TABLE IF EXISTS bwin;
CREATE TABLE bwin (id INT NOT NULL PRIMARY KEY, s VARCHAR(30) NULL, b VARBINARY(30) NULL, f DOUBLE NULL, d DECIMAL(30, 1) NULL, tm TIME(1) NULL, js JSON NULL);
INSERT INTO bwin VALUES (1, '3.7', '3.7', 3.7, 3.7, '10:00:59.5', '3.7'), (2, '2.5', '2.5', 2.5, 2.5, '10:00:00.6', '"3.7"'), (3, '-3.7', '-3.7', -3.7, -3.7, '-10:00:00.4', '18446744073709551616'), (4, '1e3', '1e3', 1000.0, 1000.0, NULL, NULL), (5, '18446744073709551615', '18446744073709551615', 1.8446744073709552e+19, 18446744073709551615.0, NULL, NULL), (6, '9223372036854775808', '9223372036854775808', 9.223372036854776e+18, 9223372036854775808.0, NULL, NULL), (7, '18446744073709551616', '18446744073709551616', 1.8446744073709552e+19, 18446744073709551616.0, NULL, NULL), (8, ' 12', ' 12', 12.0, 12.0, NULL, NULL), (9, '12abc', '12abc', NULL, NULL, NULL, NULL), (10, '-1', '-1', -1.0, -1.0, NULL, NULL), (11, '-9223372036854775809', '-9223372036854775809', -9.223372036854776e+18, -9223372036854775809.0, NULL, NULL);
SELECT id, BIT_OR(s) OVER (PARTITION BY id) AS s_window, BIT_OR(s) AS s_group, s | 0 AS s_operator FROM bwin GROUP BY id, s ORDER BY id;
SELECT id, BIT_OR(f) OVER (PARTITION BY id) AS f_window, BIT_OR(f) AS f_group, f | 0 AS f_operator FROM bwin GROUP BY id, f ORDER BY id;
SELECT id, BIT_OR(d) OVER (PARTITION BY id) AS d_window, BIT_OR(d) AS d_group, d | 0 AS d_operator FROM bwin GROUP BY id, d ORDER BY id;
SELECT id, BIT_OR(tm) OVER (PARTITION BY id) AS tm_window, BIT_OR(tm) AS tm_group, tm | 0 AS tm_operator FROM bwin GROUP BY id, tm ORDER BY id;
SELECT id, HEX(BIT_OR(b) OVER (PARTITION BY id)) AS b_window, HEX(BIT_OR(b)) AS b_group FROM bwin GROUP BY id, b ORDER BY id;
SELECT id, BIT_OR(js) OVER (PARTITION BY id) AS js_window, BIT_OR(js) AS js_group, js | 0 AS js_operator FROM bwin GROUP BY id, js ORDER BY id;
SELECT id, BIT_XOR(s) OVER (ORDER BY id) AS xor_running, BIT_AND(s) OVER (ORDER BY id) AS and_running, BIT_OR(s) OVER () AS or_all FROM bwin ORDER BY id;
DROP TABLE bwin;
DROP TABLE IF EXISTS bfr;
CREATE TABLE bfr (id INT NOT NULL PRIMARY KEY, g INT NOT NULL, v BIGINT UNSIGNED NOT NULL, w INT NOT NULL, u INT UNSIGNED NOT NULL);
INSERT INTO bfr VALUES (1, 1, 3, 3, 3), (2, 1, 18446744073709551613, -3, 2147483648), (3, 2, 9223372036854775808, -2147483648, 4294967295), (4, 2, 2147483648, 5, 1073741824), (5, 2, 12, 12, 12);
SELECT id, BIT_XOR(v) OVER () AS x_all, BIT_AND(v) OVER () AS a_all, BIT_XOR(v) OVER (PARTITION BY g) AS x_part, BIT_XOR(v) OVER (ORDER BY id) AS x_running, BIT_XOR(v) OVER (ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS x_unbounded, BIT_XOR(v) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS x_sliding, BIT_OR(v) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS o_sliding, BIT_AND(v) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS a_sliding FROM bfr ORDER BY id;
SELECT id, BIT_XOR(w) OVER (ORDER BY id) AS w_running, BIT_OR(w) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS w_sliding, BIT_XOR(u) OVER (ORDER BY id) AS u_running, BIT_OR(u) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS u_sliding, BIT_AND(u) OVER (PARTITION BY g ORDER BY id) AS u_and FROM bfr ORDER BY id;
DROP TABLE bfr;
DROP TABLE IF EXISTS bnull;
CREATE TABLE bnull (pk INT PRIMARY KEY, a INT, b INT);
INSERT INTO bnull VALUES (1, 0, NULL), (2, 0, 1), (3, 0, 2), (4, 0, NULL), (5, 0, 3), (6, 1, 7), (7, 1, NULL), (8, 1, 6);
SELECT pk, BIT_AND(b) OVER (ORDER BY pk ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS and_sliding, BIT_OR(b) OVER (ORDER BY pk ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS or_sliding, BIT_XOR(b) OVER (ORDER BY pk ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS xor_sliding FROM bnull ORDER BY pk;
SELECT pk, BIT_AND(b) OVER (ORDER BY pk) AS and_running, BIT_OR(b) OVER (ORDER BY pk) AS or_running, BIT_XOR(b) OVER (ORDER BY pk) AS xor_running, BIT_AND(b) OVER (PARTITION BY a) AS and_part, BIT_OR(b) OVER () AS or_all FROM bnull ORDER BY pk;
SELECT pk, BIT_AND(b) OVER (ORDER BY pk ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS and_rest, BIT_OR(b) OVER (ORDER BY pk ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS or_rest, BIT_XOR(b) OVER (ORDER BY pk ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS xor_rest, BIT_OR(b) OVER (ORDER BY pk ROWS BETWEEN UNBOUNDED PRECEDING AND 1 FOLLOWING) AS or_ahead, BIT_OR(b) OVER (ORDER BY pk RANGE BETWEEN 1 PRECEDING AND CURRENT ROW) AS or_range FROM bnull ORDER BY pk;
DROP TABLE bnull;
